from collections import Counter

def train_bpe(words, num_merges):
    vocab = Counter(tuple(w) for w in words)   # each word starts as characters
    merges = []
    for _ in range(num_merges):
        pairs = Counter()
        for word, freq in vocab.items():
            for a, b in zip(word, word[1:]):
                pairs[(a, b)] += freq
        if not pairs:
            break
        best = max(pairs, key=pairs.get)       # most frequent neighbours
        merges.append(best)
        vocab = Counter({merge(w, best): f for w, f in vocab.items()})
    return merges                              # the ordered merges ARE the tokenizer

def merge(word, pair):
    out, i = [], 0
    while i < len(word):
        if word[i:i + 2] == pair:
            out.append(word[i] + word[i + 1]); i += 2
        else:
            out.append(word[i]); i += 1
    return tuple(out)
